
import 'dart:convert';
import 'package:flutter/material.dart';


class FigureCours {
  final String asset; // chemin dans pubspec.yaml
  final String legende;

  const FigureCours(this.asset, this.legende);
}

class SectionCours {
  final String titre;
  final List<String> paragraphes;
  final List<String> formules;
  final String? exemple;
  final List<FigureCours> figures;

  const SectionCours({
    required this.titre,
    this.paragraphes = const [],
    this.formules = const [],
    this.exemple,
    this.figures = const [],
  });
}

class ChapitreCours {
  final int numero;
  final String titre;
  final List<SectionCours> sections;

  const ChapitreCours({
    required this.numero,
    required this.titre,
    required this.sections,
  });
}

