/// Affiche un schéma du cours (PNG en base64) avec sa légende. Zoom au pincement.
class FigureCoursWidget extends StatelessWidget {
  final FigureCours figure;
  const FigureCoursWidget({super.key, required this.figure});

  @override
  Widget build(BuildContext context) {
    // 'assets/aop/fig07.svg' -> 'fig07'
    final cle = figure.asset.split('/').last.replaceAll('.svg', '');
    final b64 = figuresAopBase64[cle];
    return Padding(
      padding: const EdgeInsets.symmetric(vertical: 12),
      child: Column(
        children: [
          Container(
            width: double.infinity,
            padding: const EdgeInsets.all(8),
            decoration: BoxDecoration(
              color: Colors.white,
              borderRadius: BorderRadius.circular(12),
              border: Border.all(color: Colors.black12),
            ),
            child: b64 == null
                ? const Text('Schéma introuvable')
                : InteractiveViewer(
                    maxScale: 4,
                    child: Image.memory(base64Decode(b64), fit: BoxFit.contain),
                  ),
          ),
          const SizedBox(height: 6),
          Text(
            figure.legende,
            textAlign: TextAlign.center,
            style: Theme.of(context).textTheme.bodySmall,
          ),
        ],
      ),
    );
  }
}


